executor_test:
import assert from "node:assert/strict";
import { energy, has_signal } from "./out/answer.js";
for (const values of [[], [0, -0], [3, -4], [0.1, 0.2, 0.3], [4096, 1, 1], [NaN]]) {
  const xs = new Float32Array(values);
  const expected = xs.reduce((s, x) => Math.fround(s + Math.fround(x * x)), 0);
  assert.equal(energy(xs), expected);
  assert.equal(has_signal(xs), expected > 0);
}
